#else
#error "META_KIND must be 1 (A2A) or 2 (AIMCP)"
#endif

struct meta_ctx { u64 arg[5], result, reserved[6]; };
struct meta_state { u64 instance, calls, failures, reserved; };
struct meta_policy { u64 run, reserved[3]; };
